CREATE TABLE `category_tree` (
  `id` int NOT NULL AUTO_INCREMENT,
  `category` int NOT NULL,
  `parent` int DEFAULT NULL,
  `is_visible` tinyint(1) DEFAULT '1' COMMENT 'indica si sera o no visible para los subdominios',
  `is_deletable` tinyint(1) DEFAULT '1' COMMENT 'indica si se puede borrar o no, asi diferenciamos las categorias por defecto de las creadas por usuarios',
  `domain` int NOT NULL COMMENT 'Identificador del Dominio',
  PRIMARY KEY (`id`),
  KEY `FK_CATEGORY_TREE_CATEGORY` (`category`),
